import {
  GRAPH_LINKS,
  GRAPH_NODES,
  type GraphLink,
  type NodeKind,
} from './data';
import {
  arrangementOf,
  LAYOUT_IDS,
  type Arrangement,
  type Box,
  type Guide,
  type LayoutId,
} from './graph-layouts';

const GLIDE_MS = 900;

const ACCOUNT_STAGGER_MS = 18;

/** Contacts follow their accounts a little later, so a layout change reads as a hand pulling the graph along. */
const CONTACT_LAG_MS = 90;

const CONTACT_STAGGER_MS = 14;

const GUIDE_FADE_MS = 450;

const MAX_PIXEL_RATIO = 2;

const GUIDE_REST = 0.01;

const LINK_ALPHA = 0.22;

const GUIDE_ALPHA = 0.1;

const PREVIEW_ALPHA = 0.5;

const SELECTED_ALPHA = 0.9;

const LINK_WIDTH = 1.1;

const PREVIEW_WIDTH = 1.5;

const SELECTED_WIDTH = 1.8;

type MovingNode = {
  id: string;
  kind: NodeKind;
  element: HTMLElement;
  halfWidth: number;
  halfHeight: number;
  x: number;
  y: number;
  fromX: number;
  fromY: number;
  toX: number;
  toY: number;
  delay: number;
};

type GuideLevels = Record<LayoutId, number>;

type EngineState = {
  canvas: HTMLCanvasElement;
  pen: CanvasRenderingContext2D;
  nodes: MovingNode[];
  byId: Map<string, MovingNode>;
  stage: Box;
  layout: LayoutId;
  arrangements: Map<LayoutId, Arrangement>;
  guideLevel: GuideLevels;
  guideGoal: GuideLevels;
  selectedId: string | null;
  previewId: string | null;
  ink: string;
  accent: string;
  isLive: boolean;
  isRevealed: boolean;
  frame: number;
  startedAt: number;
  lastTick: number;
};

export type GraphEngine = {
  setLayout: (layout: LayoutId, shouldGlide: boolean) => void;
  setHighlight: (selectedId: string | null, previewId: string | null) => void;
  setLive: (isLive: boolean) => void;
  dispose: () => void;
};

function clamp01(value: number) {
  const atLeastZero = Math.max(value, 0);
  return Math.min(atLeastZero, 1);
}

function easeInOut(progress: number) {
  if (progress < 0.5) {
    return 4 * progress * progress * progress;
  }
  const mirrored = -2 * progress + 2;
  return 1 - (mirrored * mirrored * mirrored) / 2;
}

function levelsOf(layout: LayoutId): GuideLevels {
  const levels = { cluster: 0, rings: 0, grid: 0, orbit: 0, radial: 0 };
  levels[layout] = 1;
  return levels;
}

function delayOf(kind: NodeKind, index: number) {
  if (kind === 'account') {
    return index * ACCOUNT_STAGGER_MS;
  }
  return CONTACT_LAG_MS + index * CONTACT_STAGGER_MS;
}

function nodesOf(plane: HTMLElement) {
  const nodes: MovingNode[] = [];
  const counts = { account: 0, contact: 0 };
  for (const seed of GRAPH_NODES) {
    const selector = `[data-node="${seed.id}"]`;
    const element = plane.querySelector<HTMLElement>(selector);
    if (!element) {
      continue;
    }
    const index = counts[seed.kind];
    counts[seed.kind] += 1;
    nodes.push({
      id: seed.id,
      kind: seed.kind,
      element,
      halfWidth: 0,
      halfHeight: 0,
      x: 0,
      y: 0,
      fromX: 0,
      fromY: 0,
      toX: 0,
      toY: 0,
      delay: delayOf(seed.kind, index),
    });
  }
  return nodes;
}

function readColors(state: EngineState) {
  const style = getComputedStyle(state.canvas);
  const accent = style.getPropertyValue('--primary').trim();
  state.ink = style.color;
  state.accent = accent || style.color;
}

function place(node: MovingNode) {
  const x = node.x - node.halfWidth;
  const y = node.y - node.halfHeight;
  node.element.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`;
}

function strokeGuide(pen: CanvasRenderingContext2D, guide: Guide) {
  pen.beginPath();
  if (guide.kind === 'ellipse') {
    pen.ellipse(guide.x, guide.y, guide.rx, guide.ry, 0, 0, Math.PI * 2);
  } else {
    pen.moveTo(guide.x1, guide.y1);
    pen.lineTo(guide.x2, guide.y2);
  }
  pen.stroke();
}

function drawGuides(state: EngineState) {
  const { pen } = state;
  pen.strokeStyle = state.ink;
  pen.lineWidth = 1;
  for (const id of LAYOUT_IDS) {
    const level = state.guideLevel[id];
    if (level < GUIDE_REST) {
      continue;
    }
    pen.globalAlpha = level * GUIDE_ALPHA;
    const arrangement = state.arrangements.get(id);
    for (const guide of arrangement?.guides ?? []) {
      strokeGuide(pen, guide);
    }
  }
}

function isLinkOf(link: GraphLink, id: string | null) {
  if (id === null) {
    return false;
  }
  const isAccount = link.accountId === id;
  const isContact = link.contactId === id;
  return isAccount || isContact;
}

function strokeLinks(
  state: EngineState,
  links: GraphLink[],
  color: string,
  alpha: number,
  width: number
) {
  const { pen } = state;
  pen.strokeStyle = color;
  pen.globalAlpha = alpha;
  pen.lineWidth = width;
  pen.beginPath();
  for (const link of links) {
    const account = state.byId.get(link.accountId);
    const contact = state.byId.get(link.contactId);
    if (!account || !contact) {
      continue;
    }
    pen.moveTo(account.x, account.y);
    pen.lineTo(contact.x, contact.y);
  }
  pen.stroke();
}

function draw(state: EngineState) {
  const { pen, stage } = state;
  pen.globalAlpha = 1;
  pen.lineCap = 'round';
  pen.clearRect(0, 0, stage.width, stage.height);
  drawGuides(state);
  const selected = GRAPH_LINKS.filter((link) =>
    isLinkOf(link, state.selectedId)
  );
  const previewed = GRAPH_LINKS.filter((link) =>
    isLinkOf(link, state.previewId)
  );
  const quiet = GRAPH_LINKS.filter((link) => !selected.includes(link));
  strokeLinks(state, quiet, state.ink, LINK_ALPHA, LINK_WIDTH);
  strokeLinks(state, previewed, state.accent, PREVIEW_ALPHA, PREVIEW_WIDTH);
  strokeLinks(state, selected, state.accent, SELECTED_ALPHA, SELECTED_WIDTH);
  pen.globalAlpha = 1;
}

function reveal(state: EngineState) {
  if (state.isRevealed) {
    return;
  }
  state.isRevealed = true;
  for (const node of state.nodes) {
    node.element.style.visibility = 'visible';
  }
}

function settle(state: EngineState) {
  const arrangement = state.arrangements.get(state.layout);
  for (const node of state.nodes) {
    const spot = arrangement?.places.get(node.id);
    if (spot) {
      node.x = spot.x;
      node.y = spot.y;
    }
    node.fromX = node.x;
    node.fromY = node.y;
    node.toX = node.x;
    node.toY = node.y;
    place(node);
  }
  state.guideLevel = { ...state.guideGoal };
  draw(state);
  reveal(state);
}

function measure(state: EngineState) {
  const box = state.canvas.getBoundingClientRect();
  const hasRoom = box.width > 0 && box.height > 0;
  if (!hasRoom) {
    return;
  }
  const devicePixelRatio = window.devicePixelRatio || 1;
  const pixelRatio = Math.min(devicePixelRatio, MAX_PIXEL_RATIO);
  state.stage = { width: box.width, height: box.height };
  state.canvas.width = Math.round(box.width * pixelRatio);
  state.canvas.height = Math.round(box.height * pixelRatio);
  state.pen.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
  for (const id of LAYOUT_IDS) {
    state.arrangements.set(id, arrangementOf(id, state.stage));
  }
  for (const node of state.nodes) {
    node.halfWidth = node.element.offsetWidth / 2;
    node.halfHeight = node.element.offsetHeight / 2;
  }
  settle(state);
}

function tick(state: EngineState, now: number) {
  const elapsed = now - state.startedAt;
  const sinceLast = Math.max(now - state.lastTick, 0);
  state.lastTick = now;
  let isMoving = false;
  for (const node of state.nodes) {
    const raw = (elapsed - node.delay) / GLIDE_MS;
    const progress = clamp01(raw);
    const eased = easeInOut(progress);
    node.x = node.fromX + (node.toX - node.fromX) * eased;
    node.y = node.fromY + (node.toY - node.fromY) * eased;
    place(node);
    if (progress < 1) {
      isMoving = true;
    }
  }
  const fadeStep = sinceLast / GUIDE_FADE_MS;
  let isFading = false;
  for (const id of LAYOUT_IDS) {
    const goal = state.guideGoal[id];
    const level = state.guideLevel[id];
    const gap = goal - level;
    const size = Math.min(Math.abs(gap), fadeStep);
    const next = level + Math.sign(gap) * size;
    const remaining = Math.abs(goal - next);
    const isArrived = remaining <= GUIDE_REST;
    if (isArrived) {
      state.guideLevel[id] = goal;
      continue;
    }
    state.guideLevel[id] = next;
    isFading = true;
  }
  draw(state);
  if (isMoving || isFading) {
    state.frame = requestAnimationFrame((next) => tick(state, next));
    return;
  }
  state.frame = 0;
}

function wake(state: EngineState) {
  const isAsleep = state.frame === 0;
  if (!state.isLive || !isAsleep) {
    return;
  }
  const now = performance.now();
  state.lastTick = now;
  state.frame = requestAnimationFrame((next) => tick(state, next));
}

function setLayout(state: EngineState, layout: LayoutId, shouldGlide: boolean) {
  state.layout = layout;
  state.guideGoal = levelsOf(layout);
  const arrangement = state.arrangements.get(layout);
  const wantsGlide = shouldGlide && state.isLive;
  const canGlide = wantsGlide && arrangement !== undefined;
  if (!canGlide) {
    cancelAnimationFrame(state.frame);
    state.frame = 0;
    settle(state);
    return;
  }
  for (const node of state.nodes) {
    const spot = arrangement.places.get(node.id);
    node.fromX = node.x;
    node.fromY = node.y;
    node.toX = spot?.x ?? node.x;
    node.toY = spot?.y ?? node.y;
  }
  state.startedAt = performance.now();
  wake(state);
}

function setLive(state: EngineState, isLive: boolean) {
  state.isLive = isLive;
  if (isLive) {
    return;
  }
  cancelAnimationFrame(state.frame);
  state.frame = 0;
  settle(state);
}

function setHighlight(
  state: EngineState,
  selectedId: string | null,
  previewId: string | null
) {
  state.selectedId = selectedId;
  state.previewId = previewId;
  const isRunning = state.frame !== 0;
  if (!isRunning) {
    draw(state);
  }
}

/**
 * The links and the guides of the graph are drawn on one canvas, and every node is a real button
 * the engine moves with a transform. Frames are asked for only while a layout change is gliding:
 * at rest nothing runs, and a change while the graph is off screen or under reduced motion lands at once.
 */
export function createGraphEngine(
  canvas: HTMLCanvasElement,
  plane: HTMLElement,
  layout: LayoutId
): GraphEngine | null {
  const pen = canvas.getContext('2d');
  if (!pen) {
    return null;
  }
  const nodes = nodesOf(plane);
  const byId = new Map(nodes.map((node) => [node.id, node]));
  const state: EngineState = {
    canvas,
    pen,
    nodes,
    byId,
    stage: { width: 0, height: 0 },
    layout,
    arrangements: new Map(),
    guideLevel: levelsOf(layout),
    guideGoal: levelsOf(layout),
    selectedId: null,
    previewId: null,
    ink: 'currentcolor',
    accent: 'currentcolor',
    isLive: false,
    isRevealed: false,
    frame: 0,
    startedAt: 0,
    lastTick: 0,
  };
  readColors(state);

  function onResize() {
    measure(state);
  }

  function onTheme() {
    readColors(state);
    draw(state);
  }

  measure(state);
  const sizeObserver = new ResizeObserver(onResize);
  const themeObserver = new MutationObserver(onTheme);
  sizeObserver.observe(canvas);
  themeObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class', 'data-theme'],
  });

  return {
    setLayout: (next, shouldGlide) => setLayout(state, next, shouldGlide),
    setHighlight: (selectedId, previewId) =>
      setHighlight(state, selectedId, previewId),
    setLive: (isLive) => setLive(state, isLive),
    dispose() {
      cancelAnimationFrame(state.frame);
      state.frame = 0;
      sizeObserver.disconnect();
      themeObserver.disconnect();
    },
  };
}

import { hashOf } from '@/registry/ndeko/lib/seeded';

import { ACCOUNTS, contactsOf } from './data';

export type LayoutId = 'cluster' | 'rings' | 'grid' | 'orbit' | 'radial';

export type LayoutOption = {
  value: LayoutId;
  label: string;
};

export const LAYOUT_OPTIONS: LayoutOption[] = [
  { value: 'cluster', label: 'Cluster' },
  { value: 'rings', label: 'Rings' },
  { value: 'grid', label: 'Grid' },
  { value: 'orbit', label: 'Orbit' },
  { value: 'radial', label: 'Radial' },
];

export const LAYOUT_IDS: LayoutId[] = LAYOUT_OPTIONS.map(
  (option) => option.value
);

export type Box = {
  width: number;
  height: number;
};

export type Place = {
  x: number;
  y: number;
};

export type Guide =
  | { kind: 'ellipse'; x: number; y: number; rx: number; ry: number }
  | { kind: 'line'; x1: number; y1: number; x2: number; y2: number };

export type Arrangement = {
  places: Map<string, Place>;
  guides: Guide[];
};

/** The room kept round the nodes, so no node touches the edge of the stage. */
export const STAGE_PAD_PX = 22;

const DEGREE = Math.PI / 180;

const FULL_TURN = 360;

const SIDE_TURN = FULL_TURN / ACCOUNTS.length;

function clamp(value: number, min: number, max: number) {
  const atLeastMin = Math.max(value, min);
  return Math.min(atLeastMin, max);
}

/** The same node always lands on the same offset, so a layout never shuffles between two renders. */
function jitterOf(seed: string, span: number) {
  const hash = hashOf(seed);
  const share = (hash % 1000) / 1000;
  const centred = share * 2 - 1;
  return centred * span;
}

function pointOnEllipse(
  center: Place,
  rx: number,
  ry: number,
  degrees: number
): Place {
  const angle = degrees * DEGREE;
  const offsetX = rx * Math.cos(angle);
  const offsetY = ry * Math.sin(angle);
  return { x: center.x + offsetX, y: center.y + offsetY };
}

function ellipseGuide(center: Place, rx: number, ry: number): Guide {
  return { kind: 'ellipse', x: center.x, y: center.y, rx, ry };
}

type Radii = {
  rx: number;
  ry: number;
};

/** A wide stage gets wide rings, up to twice as wide as tall, so the room beside the rings is used. */
function radiiOf(inner: Box): Radii {
  const ry = inner.height / 2;
  const widest = ry * 2;
  const rx = Math.min(inner.width / 2, widest);
  return { rx, ry };
}

function centerOf(inner: Box): Place {
  return { x: inner.width / 2, y: inner.height / 2 };
}

function sideOf(slot: number) {
  if (slot === 0) {
    return -1;
  }
  return 1;
}

function degreesOfAccount(index: number, first: number) {
  const turn = index * SIDE_TURN;
  return first + turn;
}

/** Under this width the clusters stand two across and three down, so each keeps room for its contacts. */
const NARROW_CLUSTER_PX = 360;

const CLUSTER_ANGLES = [145, 35];

type Grid = {
  columns: number;
  rows: number;
};

function clusterGridOf(inner: Box): Grid {
  if (inner.width < NARROW_CLUSTER_PX) {
    return { columns: 2, rows: 3 };
  }
  return { columns: 3, rows: 2 };
}

function clusterOf(inner: Box): Arrangement {
  const { columns, rows } = clusterGridOf(inner);
  const cellWidth = inner.width / columns;
  const cellHeight = inner.height / rows;
  const room = Math.min(cellWidth, cellHeight);
  const spread = clamp(room * 0.34, 38, 46);
  const territory = spread + 18;
  const places = new Map<string, Place>();
  const guides: Guide[] = [];
  ACCOUNTS.forEach((account, index) => {
    const column = index % columns;
    const row = Math.floor(index / columns);
    const driftX = jitterOf(`${account.id}-x`, cellWidth * 0.05);
    const driftY = jitterOf(`${account.id}-y`, cellHeight * 0.04);
    const cellX = (column + 0.5) * cellWidth;
    const cellY = (row + 0.5) * cellHeight;
    const home: Place = {
      x: cellX + driftX,
      y: cellY + driftY - spread * 0.3,
    };
    places.set(account.id, home);
    contactsOf(account.id).forEach((contact, slot) => {
      const turn = jitterOf(contact.id, 9);
      const degrees = CLUSTER_ANGLES[slot] + turn;
      const place = pointOnEllipse(home, spread, spread, degrees);
      places.set(contact.id, place);
    });
    const middle: Place = { x: home.x, y: home.y + spread * 0.33 };
    guides.push(ellipseGuide(middle, territory, territory));
  });
  return { places, guides };
}

const RING_SLOT_TURN = 14;

function ringsOf(inner: Box): Arrangement {
  const center = centerOf(inner);
  const { rx, ry } = radiiOf(inner);
  const innerRx = rx * 0.5;
  const innerRy = ry * 0.5;
  const places = new Map<string, Place>();
  ACCOUNTS.forEach((account, index) => {
    const degrees = degreesOfAccount(index, -90);
    const home = pointOnEllipse(center, innerRx, innerRy, degrees);
    places.set(account.id, home);
    contactsOf(account.id).forEach((contact, slot) => {
      const turn = sideOf(slot) * RING_SLOT_TURN;
      const outer = pointOnEllipse(center, rx, ry, degrees + turn);
      places.set(contact.id, outer);
    });
  });
  const guides = [
    ellipseGuide(center, innerRx, innerRy),
    ellipseGuide(center, rx, ry),
  ];
  return { places, guides };
}

const GRID_COLUMN_SHARES = [0.14, 0.5, 0.86];

function gridOf(inner: Box): Arrangement {
  const rowHeight = inner.height / ACCOUNTS.length;
  const places = new Map<string, Place>();
  ACCOUNTS.forEach((account, index) => {
    const y = (index + 0.5) * rowHeight;
    const accountX = inner.width * GRID_COLUMN_SHARES[0];
    places.set(account.id, { x: accountX, y });
    contactsOf(account.id).forEach((contact, slot) => {
      const x = inner.width * GRID_COLUMN_SHARES[slot + 1];
      places.set(contact.id, { x, y });
    });
  });
  return { places, guides: [] };
}

const SATELLITE_TURN = 50;

function orbitOf(inner: Box): Arrangement {
  const center = centerOf(inner);
  const { rx, ry } = radiiOf(inner);
  const orbitRx = rx * 0.68;
  const orbitRy = ry * 0.68;
  const satellite = clamp(ry * 0.34, 40, 48);
  const places = new Map<string, Place>();
  const guides: Guide[] = [ellipseGuide(center, orbitRx, orbitRy)];
  ACCOUNTS.forEach((account, index) => {
    const degrees = degreesOfAccount(index, -90);
    const home = pointOnEllipse(center, orbitRx, orbitRy, degrees);
    places.set(account.id, home);
    guides.push(ellipseGuide(home, satellite, satellite));
    contactsOf(account.id).forEach((contact, slot) => {
      const turn = sideOf(slot) * SATELLITE_TURN;
      const place = pointOnEllipse(home, satellite, satellite, degrees + turn);
      places.set(contact.id, place);
    });
  });
  return { places, guides };
}

const RADIAL_FIRST_DEGREES = -60;

const RADIAL_SLOT_TURN = 11;

function radialOf(inner: Box): Arrangement {
  const center = centerOf(inner);
  const { rx, ry } = radiiOf(inner);
  const nearRx = rx * 0.4;
  const nearRy = ry * 0.4;
  const places = new Map<string, Place>();
  const guides: Guide[] = [];
  ACCOUNTS.forEach((account, index) => {
    const degrees = degreesOfAccount(index, RADIAL_FIRST_DEGREES);
    const near = pointOnEllipse(center, nearRx, nearRy, degrees);
    const far = pointOnEllipse(center, rx, ry, degrees);
    places.set(account.id, near);
    guides.push({
      kind: 'line',
      x1: center.x,
      y1: center.y,
      x2: far.x,
      y2: far.y,
    });
    contactsOf(account.id).forEach((contact, slot) => {
      const turn = sideOf(slot) * RADIAL_SLOT_TURN;
      const outer = pointOnEllipse(center, rx, ry, degrees + turn);
      places.set(contact.id, outer);
    });
  });
  return { places, guides };
}

const ARRANGERS: Record<LayoutId, (inner: Box) => Arrangement> = {
  cluster: clusterOf,
  rings: ringsOf,
  grid: gridOf,
  orbit: orbitOf,
  radial: radialOf,
};

function shiftedGuide(guide: Guide): Guide {
  if (guide.kind === 'ellipse') {
    return {
      ...guide,
      x: guide.x + STAGE_PAD_PX,
      y: guide.y + STAGE_PAD_PX,
    };
  }
  return {
    kind: 'line',
    x1: guide.x1 + STAGE_PAD_PX,
    y1: guide.y1 + STAGE_PAD_PX,
    x2: guide.x2 + STAGE_PAD_PX,
    y2: guide.y2 + STAGE_PAD_PX,
  };
}

export function arrangementOf(layout: LayoutId, stage: Box): Arrangement {
  const room = STAGE_PAD_PX * 2;
  const inner: Box = {
    width: Math.max(stage.width - room, 1),
    height: Math.max(stage.height - room, 1),
  };
  const raw = ARRANGERS[layout](inner);
  const places = new Map<string, Place>();
  for (const [id, place] of raw.places) {
    const x = place.x + STAGE_PAD_PX;
    const y = place.y + STAGE_PAD_PX;
    places.set(id, { x, y });
  }
  const guides = raw.guides.map(shiftedGuide);
  return { places, guides };
}

export function layoutNameOf(layout: LayoutId) {
  const option = LAYOUT_OPTIONS.find((candidate) => candidate.value === layout);
  return option?.label ?? '';
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import {
  accountOf,
  contactOf,
  spokenNodeOf,
  type GraphNode,
  type NodeKind,
} from './data';

/** The engine reveals a node once it knows where the node stands, so none is ever seen at the corner. */
const HIDDEN: React.CSSProperties = { visibility: 'hidden' };

const NODE =
  'absolute top-0 left-0 grid cursor-pointer place-items-center outline-none transition-[opacity,box-shadow,scale,background-color] duration-150 ease-(--ease-out-strong) hover:bg-foreground/[0.05] focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card active:scale-[0.94]';

const SHAPE: Record<NodeKind, string> = {
  account: 'size-9 rounded-lg',
  contact: 'size-8 rounded-full',
};

const SELECTED_RING = 'ring-2 ring-primary ring-offset-2 ring-offset-card';

function selectedClassOf(isSelected: boolean) {
  if (isSelected) {
    return SELECTED_RING;
  }
  return undefined;
}

function dimmedClassOf(isDimmed: boolean) {
  if (isDimmed) {
    return 'opacity-40';
  }
  return undefined;
}

function Face({ node }: { node: GraphNode }) {
  if (node.kind === 'account') {
    const account = accountOf(node.id);
    return <CompanyMark seed={account.name} size='lg' />;
  }
  const contact = contactOf(node.id);
  const name = contact?.name ?? node.id;
  return <Avatar className='size-6' seed={name} />;
}

type GraphNodeButtonProps = {
  node: GraphNode;
  isSelected: boolean;
  isDimmed: boolean;
  isPressed: boolean;
  tabIndex: 0 | -1;
  onSelect: (id: string) => void;
  onPreview: (id: string | null) => void;
  onFocusNode: (id: string) => void;
};

export function GraphNodeButton({
  node,
  isSelected,
  isDimmed,
  isPressed,
  tabIndex,
  onSelect,
  onPreview,
  onFocusNode,
}: GraphNodeButtonProps) {
  const { id } = node;

  function select() {
    onSelect(id);
  }

  function preview() {
    onPreview(id);
  }

  function endPreview() {
    onPreview(null);
  }

  function focusNode() {
    onFocusNode(id);
    onPreview(id);
  }

  return (
    <button
      type='button'
      data-node={id}
      aria-label={spokenNodeOf(id)}
      aria-pressed={isSelected}
      tabIndex={tabIndex}
      style={HIDDEN}
      onClick={select}
      onPointerEnter={preview}
      onPointerLeave={endPreview}
      onFocus={focusNode}
      onBlur={endPreview}
      className={cn(
        NODE,
        SHAPE[node.kind],
        selectedClassOf(isSelected),
        dimmedClassOf(isDimmed),
        pressedQuietOf(isPressed)
      )}
    >
      <Face node={node} />
    </button>
  );
}

'use client';

import { useId, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { countOf } from '@/registry/ndeko/lib/words';

import { NEW_LEADS, TREND_WEEKS } from './data';
import { rovingTargetOf } from './roving';

const VIEW_WIDTH = 1000;

const PLOT_HEIGHT = 144;

const TOP_VALUE = 80;

const TICKS = [0, 40, 80];

const LAST_INDEX = NEW_LEADS.length - 1;

const LABEL_EVERY = 3;

function yOf(value: number) {
  const share = value / TOP_VALUE;
  return PLOT_HEIGHT - share * PLOT_HEIGHT;
}

function xShareOf(index: number) {
  return index / LAST_INDEX;
}

function commandLetterOf(index: number) {
  if (index === 0) {
    return 'M';
  }
  return 'L';
}

function linePathOf() {
  const commands = NEW_LEADS.map((value, index) => {
    const x = xShareOf(index) * VIEW_WIDTH;
    const y = yOf(value);
    const letter = commandLetterOf(index);
    return `${letter}${x.toFixed(1)} ${y.toFixed(1)}`;
  });
  return commands.join(' ');
}

const LINE_PATH = linePathOf();

const AREA_PATH = `${LINE_PATH} L${VIEW_WIDTH} ${PLOT_HEIGHT} L0 ${PLOT_HEIGHT} Z`;

function isLabeled(index: number) {
  const fromLast = LAST_INDEX - index;
  return fromLast % LABEL_EVERY === 0;
}

const LABELED = TREND_WEEKS.map((week, index) => ({ week, index })).filter(
  ({ index }) => isLabeled(index)
);

function clampIndex(index: number) {
  const atLeastFirst = Math.max(index, 0);
  return Math.min(atLeastFirst, LAST_INDEX);
}

function weekLabelOf(index: number) {
  if (index === LAST_INDEX) {
    return 'This week';
  }
  return `Week of ${TREND_WEEKS[index]}`;
}

function changeOf(index: number) {
  if (index === 0) {
    return 'the first week shown';
  }
  const before = NEW_LEADS[index - 1];
  const difference = NEW_LEADS[index] - before;
  const ratio = difference / before;
  const percent = Math.round(ratio * 100);
  if (percent === 0) {
    return 'level with the week before';
  }
  if (percent > 0) {
    return `up ${percent}% on the week before`;
  }
  return `down ${Math.abs(percent)}% on the week before`;
}

export function LeadTrend() {
  const titleId = useId();
  const [reading, setReading] = useState<number | null>(null);
  const shownIndex = reading ?? LAST_INDEX;
  const value = NEW_LEADS[shownIndex];
  const label = weekLabelOf(shownIndex);
  const caption = `${label}, ${changeOf(shownIndex)}`;
  const guideShare = xShareOf(shownIndex);
  const spoken = `${TREND_WEEKS[shownIndex]}, ${countOf(value, 'new lead')}`;

  function readFromPointer(event: React.PointerEvent<HTMLDivElement>) {
    const box = event.currentTarget.getBoundingClientRect();
    const ratio = (event.clientX - box.left) / box.width;
    const index = Math.round(ratio * LAST_INDEX);
    setReading(clampIndex(index));
  }

  function readFromKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      setReading(null);
      return;
    }
    const next = rovingTargetOf(event.key, shownIndex, NEW_LEADS.length);
    if (next === null) {
      return;
    }
    event.preventDefault();
    setReading(next);
  }

  function stopReading() {
    setReading(null);
  }

  return (
    <section
      aria-labelledby={titleId}
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <header className='flex flex-col gap-1'>
        <h2 id={titleId} className='text-sm font-medium'>
          New leads
        </h2>
        <p className='flex items-baseline gap-1.5'>
          <MotionNumber
            value={value}
            className='text-2xl leading-8 font-semibold'
          />
          <span className='text-muted-foreground text-[13px]'>new leads</span>
        </p>
        <p className='text-muted-foreground text-xs'>{caption}</p>
      </header>
      <div className='grid grid-cols-[auto_minmax(0,1fr)] gap-x-2'>
        <div
          aria-hidden='true'
          className='relative w-6 shrink-0'
          style={{ height: PLOT_HEIGHT }}
        >
          {TICKS.map((tick) => (
            <span
              key={tick}
              className='text-muted-foreground absolute right-0 -translate-y-1/2 text-[11px] tabular-nums'
              style={{ top: yOf(tick) }}
            >
              {tick}
            </span>
          ))}
        </div>
        <div
          role='slider'
          tabIndex={0}
          aria-label='New leads by week. The arrow keys read each week'
          aria-orientation='horizontal'
          aria-valuemin={0}
          aria-valuemax={LAST_INDEX}
          aria-valuenow={shownIndex}
          aria-valuetext={spoken}
          onPointerMove={readFromPointer}
          onPointerLeave={stopReading}
          onKeyDown={readFromKeys}
          onBlur={stopReading}
          className='focus-visible:ring-ring/25 @container relative touch-pan-y rounded-md outline-none focus-visible:ring-[3px]'
          style={{ height: PLOT_HEIGHT }}
        >
          {TICKS.map((tick) => (
            <span
              key={tick}
              aria-hidden='true'
              className='hairline-t border-border pointer-events-none absolute inset-x-0'
              style={{ top: yOf(tick) }}
            />
          ))}
          <svg
            aria-hidden='true'
            viewBox={`0 0 ${VIEW_WIDTH} ${PLOT_HEIGHT}`}
            preserveAspectRatio='none'
            className='pointer-events-none absolute inset-0 size-full overflow-visible'
          >
            <path d={AREA_PATH} className='fill-primary/10' />
            <path
              d={LINE_PATH}
              vectorEffect='non-scaling-stroke'
              className='stroke-primary fill-none stroke-2 [stroke-linecap:round] [stroke-linejoin:round]'
            />
          </svg>
          <div
            aria-hidden='true'
            className='pointer-events-none absolute inset-y-0 left-0 w-0 transition-transform duration-150 ease-(--ease-out-strong)'
            style={{ transform: `translateX(${guideShare * 100}cqw)` }}
          >
            <span className='bg-foreground/15 absolute inset-y-0 w-px -translate-x-1/2' />
            <span
              className='bg-primary ring-card absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full ring-2 transition-[top] duration-150 ease-(--ease-out-strong)'
              style={{ top: yOf(value) }}
            />
          </div>
        </div>
        <div className='col-start-2 row-start-2 mt-2 h-4'>
          <div aria-hidden='true' className='relative'>
            {LABELED.map(({ week, index }) => (
              <span
                key={week}
                className='text-muted-foreground absolute top-0 text-[11px] whitespace-nowrap tabular-nums'
                style={{
                  left: `${xShareOf(index) * 100}%`,
                  transform: `translateX(-${xShareOf(index) * 100}%)`,
                }}
              >
                {week}
              </span>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';

const MORPH: Transition = { duration: 0.45, ease: EASE_OUT_STRONG };

function transitionOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH;
}

type MorphPathProps = {
  d: string;
  className?: string;
  style?: React.CSSProperties;
};

/** A shape that glides to its new outline when the data changes, as long as both outlines have the same number of points. */
export function MorphPath({ d, className, style }: MorphPathProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.path
      initial={false}
      animate={{ d }}
      transition={transitionOf(shouldReduceMotion)}
      vectorEffect='non-scaling-stroke'
      className={className}
      style={style}
    />
  );
}

