'use client';

import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';

import { STAGES } from './data';
import { MorphPath } from './morph-path';

const VIEW_WIDTH = 1000;

const ROW_HEIGHT = 40;

const ROW_GAP = 4;

const MIN_SHARE = 0.12;

const NECK = 0.86;

const FUNNEL_HEIGHT = ROW_HEIGHT * STAGES.length;

/** The first four stages are the primary colour, fading as the funnel narrows. The last one is a won deal. */
const ROW_FILL = [
  'fill-primary/90',
  'fill-primary/75',
  'fill-primary/60',
  'fill-primary/45',
  'fill-success/80',
];

function sharesOf(counts: number[]) {
  const first = counts[0];
  return counts.map((count) => {
    if (first === 0) {
      return MIN_SHARE;
    }
    return Math.max(count / first, MIN_SHARE);
  });
}

function bottomShareOf(index: number, shares: number[]) {
  const next = shares[index + 1];
  if (next === undefined) {
    return shares[index] * NECK;
  }
  return next;
}

/** A row runs from the width of its stage to the width of the next one, so the rows join into one funnel. */
function rowPathOf(index: number, shares: number[]) {
  const half = VIEW_WIDTH / 2;
  const topHalf = shares[index] * half;
  const bottomHalf = bottomShareOf(index, shares) * half;
  const top = index * ROW_HEIGHT + ROW_GAP / 2;
  const bottom = (index + 1) * ROW_HEIGHT - ROW_GAP / 2;
  const topLeft = half - topHalf;
  const topRight = half + topHalf;
  const bottomLeft = half - bottomHalf;
  const bottomRight = half + bottomHalf;
  return `M${topLeft} ${top} L${topRight} ${top} L${bottomRight} ${bottom} L${bottomLeft} ${bottom} Z`;
}

function moveOnOf(count: number, before: number) {
  if (before === 0) {
    return 0;
  }
  return Math.round((count / before) * 100);
}

type PipelineFunnelProps = {
  counts: number[];
};

export function PipelineFunnel({ counts }: PipelineFunnelProps) {
  const titleId = useId();
  const shares = sharesOf(counts);

  return (
    <section
      data-section='pipeline'
      aria-labelledby={titleId}
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex scroll-mt-4 flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <header className='flex flex-col leading-tight'>
        <h2 id={titleId} className='text-sm font-medium'>
          Pipeline
        </h2>
        <p className='text-muted-foreground text-xs'>
          Deals that reached each stage
        </p>
      </header>
      <div className='grid grid-cols-[9.5rem_minmax(0,1fr)] gap-x-3'>
        <ol aria-label='Deals by stage' className='flex flex-col'>
          {STAGES.map((stage, index) => {
            const before = counts[index - 1] ?? 0;
            const share = moveOnOf(counts[index], before);
            const hasShare = index > 0;
            return (
              <li
                key={stage.id}
                className='flex h-10 items-center gap-2 text-[13px]'
              >
                <span className='text-muted-foreground min-w-0 flex-1 truncate'>
                  {stage.label}
                </span>
                <MotionNumber
                  value={counts[index]}
                  className='w-9 justify-end font-medium'
                />
                <span
                  className={cn(
                    'text-muted-foreground hidden w-9 text-end text-xs tabular-nums @md/page:block',
                    !hasShare && 'invisible'
                  )}
                >
                  {share}%<span className='sr-only'> of the stage before</span>
                </span>
              </li>
            );
          })}
        </ol>
        <svg
          aria-hidden='true'
          viewBox={`0 0 ${VIEW_WIDTH} ${FUNNEL_HEIGHT}`}
          preserveAspectRatio='none'
          className='w-full overflow-visible'
          style={{ height: FUNNEL_HEIGHT }}
        >
          {STAGES.map((stage, index) => (
            <MorphPath
              key={stage.id}
              d={rowPathOf(index, shares)}
              className={ROW_FILL[index]}
            />
          ))}
        </svg>
      </div>
    </section>
  );
}

export function rovingTargetOf(key: string, current: number, count: number) {
  const last = count - 1;
  if (key === 'ArrowRight' || key === 'ArrowDown') {
    return Math.min(current + 1, last);
  }
  if (key === 'ArrowLeft' || key === 'ArrowUp') {
    return Math.max(current - 1, 0);
  }
  if (key === 'Home') {
    return 0;
  }
  if (key === 'End') {
    return last;
  }
  return null;
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { restingOf } from '@/registry/ndeko/lib/run-session';
import { countOf } from '@/registry/ndeko/lib/words';

import {
  AGENT_TASK,
  DEMO_TASK,
  DENIED_NOTE,
  eventsOfDay,
  RUN_COPY,
  RUNS,
  spokenNodeOf,
  STAGE_COUNTS_AFTER,
  STAGE_COUNTS_BEFORE,
  STRIP,
  taskOf,
  TASKS,
  type RunId,
  type RunStatus,
} from './data';
import { layoutNameOf, type LayoutId } from './graph-layouts';

export type Decision = 'approved' | 'denied';

export type RunLive = {
  status: RunStatus;
  note: string;
};

export type CrmState = {
  isLoaded: boolean;
  layout: LayoutId;
  selectedId: string | null;
  taskIds: string[];
  doneTaskIds: string[];
  runs: Record<RunId, RunLive>;
  stageCounts: number[];
  dayIndex: number | null;
  isSidebarOpen: boolean;
  spoken: string;
};

export type CrmAction =
  | { type: 'loaded' }
  | { type: 'layoutSet'; layout: LayoutId }
  | { type: 'nodeSelected'; id: string | null }
  | { type: 'taskToggled'; id: string }
  | { type: 'taskAdded'; id: string }
  | { type: 'runStarted'; id: RunId }
  | { type: 'runFinished'; id: RunId }
  | { type: 'decided'; id: RunId; decision: Decision }
  | { type: 'funnelUpdated' }
  | { type: 'daySelected'; index: number | null }
  | { type: 'sidebar'; isOpen: boolean }
  | { type: 'batch'; actions: CrmAction[] };

type Step = SessionStep<CrmState, CrmAction>;

const MERGE: RunId = 'merge';

function runsOf(): Record<RunId, RunLive> {
  const quiet: RunLive = { status: 'done', note: '' };
  const runs: Record<RunId, RunLive> = {
    enrich: quiet,
    qualify: quiet,
    drafts: quiet,
    merge: quiet,
  };
  for (const seed of RUNS) {
    runs[seed.id] = { status: seed.status, note: seed.note };
  }
  return runs;
}

export const INITIAL: CrmState = {
  isLoaded: false,
  layout: 'cluster',
  selectedId: null,
  taskIds: TASKS.map((task) => task.id),
  doneTaskIds: [],
  runs: runsOf(),
  stageCounts: STAGE_COUNTS_BEFORE,
  dayIndex: null,
  isSidebarOpen: false,
  spoken: '',
};

function spokenSelectionOf(id: string | null) {
  if (id === null) {
    return 'Selection cleared';
  }
  return spokenNodeOf(id);
}

function taskToggled(state: CrmState, id: string): CrmState {
  const task = taskOf(id);
  const isDone = state.doneTaskIds.includes(id);
  if (isDone) {
    const doneTaskIds = state.doneTaskIds.filter((doneId) => doneId !== id);
    return { ...state, doneTaskIds, spoken: `${task.title}, open again` };
  }
  const doneTaskIds = [...state.doneTaskIds, id];
  return { ...state, doneTaskIds, spoken: `${task.title}, done` };
}

function taskAdded(state: CrmState, id: string): CrmState {
  const isKnown = state.taskIds.includes(id);
  if (isKnown) {
    return state;
  }
  const taskIds = [id, ...state.taskIds];
  return { ...state, taskIds };
}

function runPatched(
  state: CrmState,
  id: RunId,
  from: RunStatus,
  to: RunLive
): CrmState {
  const run = state.runs[id];
  if (run.status !== from) {
    return state;
  }
  return { ...state, runs: { ...state.runs, [id]: to } };
}

function runStarted(state: CrmState, id: RunId): CrmState {
  const live: RunLive = { status: 'running', note: RUN_COPY[id].running };
  return runPatched(state, id, 'queued', live);
}

function runFinished(state: CrmState, id: RunId): CrmState {
  const live: RunLive = { status: 'done', note: RUN_COPY[id].done };
  return runPatched(state, id, 'running', live);
}

function decided(state: CrmState, id: RunId, decision: Decision): CrmState {
  if (decision === 'approved') {
    const live: RunLive = { status: 'running', note: RUN_COPY[id].running };
    const next = runPatched(state, id, 'waiting', live);
    return { ...next, spoken: 'Allowed. Scout merges the duplicates' };
  }
  const live: RunLive = { status: 'done', note: DENIED_NOTE };
  const next = runPatched(state, id, 'waiting', live);
  return { ...next, spoken: 'Denied. Nothing is merged' };
}

function spokenDayOf(index: number | null) {
  if (index === null) {
    return 'No day selected';
  }
  const day = STRIP[index];
  const events = eventsOfDay(index);
  const count = countOf(events.length, 'event');
  return `${day.spoken}, ${count}`;
}

export function reducer(state: CrmState, action: CrmAction): CrmState {
  switch (action.type) {
    case 'loaded':
      return { ...state, isLoaded: true };
    case 'layoutSet': {
      const name = layoutNameOf(action.layout);
      return { ...state, layout: action.layout, spoken: `${name} layout` };
    }
    case 'nodeSelected': {
      const spoken = spokenSelectionOf(action.id);
      return { ...state, selectedId: action.id, spoken };
    }
    case 'taskToggled':
      return taskToggled(state, action.id);
    case 'taskAdded':
      return taskAdded(state, action.id);
    case 'runStarted':
      return runStarted(state, action.id);
    case 'runFinished':
      return runFinished(state, action.id);
    case 'decided':
      return decided(state, action.id, action.decision);
    case 'funnelUpdated':
      return { ...state, stageCounts: STAGE_COUNTS_AFTER };
    case 'daySelected': {
      const spoken = spokenDayOf(action.index);
      return { ...state, dayIndex: action.index, spoken };
    }
    case 'sidebar':
      return { ...state, isSidebarOpen: action.isOpen };
    case 'batch': {
      let next = state;
      for (const inner of action.actions) {
        next = reducer(next, inner);
      }
      return next;
    }
  }
}

export function openTaskCount(state: CrmState) {
  const open = state.taskIds.filter((id) => !state.doneTaskIds.includes(id));
  return open.length;
}

function hasDecided(state: CrmState) {
  return state.runs[MERGE].status !== 'waiting';
}

const DEMO_DECIDES_AFTER_MS = 2000;

const SWITCH_MS = 2600;

function layoutStep(after: number, layout: LayoutId): Step {
  return { after, by: 'demo', action: { type: 'layoutSet', layout } };
}

function frame(after: number, actions: CrmAction[]): Step {
  return { after, action: { type: 'batch', actions } };
}

const OPENING: Step[] = [
  { after: 700, action: { type: 'loaded' } },
  layoutStep(1900, 'rings'),
  layoutStep(SWITCH_MS, 'grid'),
  layoutStep(SWITCH_MS, 'orbit'),
  layoutStep(SWITCH_MS, 'radial'),
  {
    after: SWITCH_MS,
    by: 'demo',
    press: 'node-esther',
    action: { type: 'nodeSelected', id: 'esther' },
  },
  layoutStep(SWITCH_MS, 'cluster'),
  frame(2400, [
